import { Component } from '@angular/core';
import { candidate } from '../candiates';
@Component({
  selector: 'app-reg',
  templateUrl: './reg.component.html',
  styleUrls: ['./reg.component.css']
})
export class RegComponent {
  candiateList:candidate[]=[{
    id:'#ab123',
    date:'june 1,2024, 8:22 AM',
    company:'google',
    type:'freelancer',
    position:'internal UI Designer',
    contact:'',
    staus:'pending'
  },
  {
    id:'#ab456',
    date:'june 1,2024, 8:22 AM',
    company:'google',
    type:'freelancer',
    position:'internal UI Designer',
    contact:'',
    staus:'On-hold'
  },
  {
    id:'#ab126',
    date:'june 1,2024, 8:22 AM',
    company:'google',
    type:'freelancer',
    position:'internal UI Designer',
    contact:'',
    staus:'candidate'
  },
  {
    id:'#ab127',
    date:'june 1,2024, 8:22 AM',
    company:'nykaa',
    type:'freelancer',
    position:'internal UI Designer',
    contact:'',
    staus:'pending'
  },
  {
    id:'#ab163',
    date:'june 1,2024, 8:22 AM',
    company:'nykaa',
    type:'freelancer',
    position:'internal UI Designer',
    contact:'',
    staus:'on-hold'
  },
  {
    id:'#ab223',
    date:'june 1,2024, 8:22 AM',
    company:'flipkart',
    type:'freelancer',
    position:'internal UI Designer',
    contact:'',
    staus:'candidate'
  },]
  
  filteredCandidateList=this.candiateList
  
  filter(value:string){
    
    if(value=='all'){
     this.filteredCandidateList=this.candiateList
    }
    else{
      this.filteredCandidateList=this.candiateList.filter(obj => obj.staus.toLowerCase() == value.toLowerCase())
    
    }

  }
}
